questionvariables.text:
N:15;
SHOTS:30;
base:40+5*rand(5);
/* Patch heights in 5-unit steps above base. Yield falls 5 per step away from a centre, */
/* down to poor soil at base-10 far from every patch. Field range is 35 or 40. */
heights:[4,5,5+rand(2)];
/* Centres stay 2 or more plots from the edge so each patch's signal is not cut off, and are */
/* far enough apart to be separate peaks. Re-roll until they are. */
mdist(p,q):=abs(p[1]-q[1])+abs(p[2]-q[2]);
apart(c):=is(mdist(c[1],c[2])>=max(heights[1],heights[2])+2 and mdist(c[1],c[3])>=max(heights[1],heights[3])+2 and mdist(c[2],c[3])>=max(heights[2],heights[3])+2);
centres:makelist([2+rand(N-4),2+rand(N-4)],k,1,3);
while not apart(centres) do centres:makelist([2+rand(N-4),2+rand(N-4)],k,1,3);
/* Plot index (0-based, row by row) of each patch centre. */
cidx:makelist(centres[k][2]*N+centres[k][1],k,1,3);
yield_at(i):=block([x,y],x:mod(i,N),y:floor(i/N),
 base+5*lmax(makelist(max(-2,heights[k]-abs(x-centres[k][1])-abs(y-centres[k][2])),k,1,3)));
field:makelist(yield_at(i),i,0,N*N-1);
field_min:lmin(field);
field_max:lmax(field);
field_range:field_max-field_min;
/* Helpers used by the marking: clean up the list of shots and look up their yields. */
clean_picks(p):=block([q],
 q:if listp(p) then sublist(p,lambda([v],is(integerp(v) and v>=0 and v<N*N))) else [],
 unique(makelist(q[k],k,1,min(SHOTS,length(q)))));
